@extends('layouts.app') @section('title','#'.$ticket->number.' — '.$ticket->title) @section('content')<div class="page-head"><div><p class="eyebrow">#{{ $ticket->number }}</p><h1>{{ $ticket->title }}</h1></div><span class="status large" style="--status:{{ $ticket->status->color }}">{{ $ticket->status->name }}</span></div><div class="ticket-layout"><section><article class="panel"><p>{{ $ticket->description }}</p></article><article class="panel"><h2>Atividade</h2>@forelse($ticket->comments as $comment)<div class="comment"><b>{{ $comment->user?->name ?? $ticket->requester_name }}</b><span>{{ $comment->visibility==='public'?'Público':'Nota interna' }}</span><p>{{ $comment->body }}</p></div>@empty<p class="muted">Nenhum comentário ainda.</p>@endforelse</article></section><aside class="panel details"><h2>Detalhes</h2><dl><dt>Prioridade</dt><dd>{{ ucfirst($ticket->priority) }}</dd><dt>Responsável</dt><dd>{{ $ticket->assignee?->name ?? 'Não atribuído' }}</dd><dt>Prazo</dt><dd>{{ $ticket->due_at?->format('d/m/Y H:i') }}</dd><dt>Origem</dt><dd>{{ $ticket->origin==='internal'?'Interno':'Sistema integrado' }}</dd></dl><h3>Checklist</h3>@forelse($ticket->checklist as $item)<label class="check"><input type="checkbox" @checked($item->completed) disabled>{{ $item->text }}</label>@empty<p class="muted">Sem itens.</p>@endforelse</aside></div>@endsection
